#!/usr/bin/env python3
# AI DISCLAIMER: All of the text in this file was generated by AI.
"""W010 scorer: prove seconds per proof for each multiexp arm and input count (median [range] over the seeds), the
change of each pair of arms in percent with an overlap check, and the correctness checks (every run ok; for each case
the three arms' proofs byte-identical).
usage: python3 score_w010.py results.csv"""
import collections, csv, statistics, sys

if len(sys.argv) != 2:
    sys.exit(__doc__)
rows = list(csv.DictReader(open(sys.argv[1])))
ARMS = ["m051", "m052", "s4"]
LABEL = {"m051": "multiexp 0.5.1", "m052": "multiexp 0.5.2", "s4": "0.5.2 + Straus(4)"}
t = collections.defaultdict(list)
shas = collections.defaultdict(set)
bad = [r for r in rows if r["rc"] != "0" or not r["prove_s"]]
for r in rows:
    if r["rc"] == "0" and r["prove_s"]:
        t[(r["arm"], int(r["n_inputs"]))].append(float(r["prove_s"]))
        shas[(int(r["n_inputs"]), r["layers"], r["seed"])].add(r["proof_sha256"])
ns = sorted({n for (_, n) in t})
print("runs: %d, failed: %d" % (len(rows), len(bad)))
for r in bad:
    print("FAILED", r)
same = sum(1 for v in shas.values() if len(v) == 1)
print("cases: %d; proofs byte-identical across the arms: %d of %d" % (len(shas), same, len(shas)))
print()
print("prove seconds per proof, median [range] over seeds (runs)")
print("| inputs | " + " | ".join(LABEL[a] for a in ARMS) + " |")
print("|---|" + "---|" * len(ARMS))
for n in ns:
    cells = []
    for a in ARMS:
        v = t.get((a, n), [])
        cells.append("%.2f [%.2f-%.2f] (%d)" % (statistics.median(v), min(v), max(v), len(v)) if v else "-")
    print("| %d | %s |" % (n, " | ".join(cells)))
print()
print("change in median prove time")
PAIRS = [("m052", "m051"), ("s4", "m052"), ("s4", "m051")]
print("| inputs | " + " | ".join("%s vs %s" % (LABEL[a], LABEL[b]) for a, b in PAIRS) + " |")
print("|---|" + "---|" * len(PAIRS))
for n in ns:
    cells = []
    for a, b in PAIRS:
        x, y = t.get((a, n), []), t.get((b, n), [])
        if not x or not y:
            cells.append("-")
            continue
        r = statistics.median(x) / statistics.median(y)
        ov = "no overlap" if max(x) < min(y) or min(x) > max(y) else "overlap"
        cells.append("%+.1f%% (ratio %.3f, %.1fx faster; %s)" % ((r - 1) * 100, r, 1 / r, ov))
    print("| %d | %s |" % (n, " | ".join(cells)))
